@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap');

:root {
  --primary: #0051C3;
  --primary-dark: #003a8c;
  --accent: #DE5052;
  --accent-hover: #c44547;
  --bg-color: #FFFFFF;
  --bg-light: #F8FAFC;
  --bg-dark: #0F172A;
  --text-main: #0F172A;
  --text-muted: #475569;
  --border-color: #E2E8F0;
  --font-heading: 'Plus Jakarta Sans', sans-serif;
  --font-body: 'Inter', sans-serif;
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --radius: 12px;
  --radius-full: 9999px;
  --transition: all 0.2s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-body);
  color: var(--text-main);
  background-color: var(--bg-color);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--text-main);
  line-height: 1.2;
}

h1 { font-size: 3.5rem; font-weight: 800; letter-spacing: -0.02em; }
h2 { font-size: 2.5rem; font-weight: 700; letter-spacing: -0.01em; }
h3 { font-size: 1.5rem; font-weight: 600; }

p {
  color: var(--text-muted);
  font-size: 1.125rem;
}

a {
  text-decoration: none;
  color: inherit;
  transition: var(--transition);
}

ul { list-style: none; }

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 1.5rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font-body);
  border: 2px solid transparent;
  font-size: 1rem;
}

.btn-primary {
  background-color: var(--accent);
  color: white;
}
.btn-primary:hover {
  background-color: var(--accent-hover);
  transform: translateY(-1px);
}

.btn-secondary {
  background-color: var(--bg-color);
  color: var(--text-main);
  border-color: var(--border-color);
}
.btn-secondary:hover {
  background-color: var(--bg-light);
  border-color: var(--text-muted);
}

/* Header & Nav */
.header {
  position: sticky;
  top: 0;
  background-color: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(8px);
  z-index: 100;
  border-bottom: 1px solid var(--border-color);
}

.nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 80px;
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.logo-icon {
  width: 28px;
  height: 28px;
  background-color: var(--primary);
  border-radius: 6px;
  display: inline-block;
  position: relative;
}
.logo-icon::after {
  content: "";
  position: absolute;
  top: 6px; left: 6px; right: 6px; bottom: 6px;
  background-color: var(--accent);
  border-radius: 3px;
}

.nav-links {
  display: flex;
  gap: 2rem;
  align-items: center;
}

.nav-links a {
  font-weight: 500;
  color: var(--text-muted);
}
.nav-links a:hover, .nav-links a.active {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  gap: 1rem;
  align-items: center;
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  color: var(--text-main);
}

/* Mobile Nav Drawer */
.mobile-drawer {
  position: fixed;
  top: 80px;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--bg-color);
  z-index: 99;
  padding: 2rem;
  transform: translateX(100%);
  transition: transform 0.3s ease;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}
.mobile-drawer.open {
  transform: translateX(0);
}
.mobile-drawer a {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text-main);
}

/* Sections */
.section {
  padding: 6rem 0;
}
.section-light { background-color: var(--bg-light); }
.section-dark { background-color: var(--bg-dark); color: white; }
.section-dark h1, .section-dark h2, .section-dark h3 { color: white; }
.section-dark p { color: #CBD5E1; }

.section-header {
  text-align: center;
  max-width: 800px;
  margin: 0 auto 4rem auto;
}
.section-header h2 { margin-bottom: 1rem; }

/* Hero */
.hero {
  padding: 8rem 0 6rem 0;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-light) 0%, var(--bg-color) 100%);
}
.hero-content {
  max-width: 900px;
  margin: 0 auto;
}
.hero h1 {
  margin-bottom: 1.5rem;
}
.hero p {
  font-size: 1.25rem;
  margin-bottom: 2.5rem;
  max-width: 700px;
  margin-inline: auto;
}
.hero-actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
}

/* Grid Layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 4rem; align-items: center; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 2rem; }

/* Cards */
.card {
  background-color: var(--bg-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 2rem;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
  height: 100%;
}
.card:hover {
  box-shadow: var(--shadow);
  transform: translateY(-2px);
}
.card-icon {
  width: 48px; height: 48px;
  background-color: var(--bg-light);
  color: var(--primary);
  border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
}
.card h3 { margin-bottom: 0.75rem; }

/* Stats Banner */
.stats-banner {
  background-color: var(--primary);
  color: white;
  padding: 4rem 0;
  text-align: center;
}
.stat-item h3 {
  font-size: 3.5rem;
  font-weight: 800;
  color: white;
  margin-bottom: 0.5rem;
}
.stat-item p {
  color: rgba(255,255,255,0.8);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: 0.875rem;
}

/* Testimonial Carousel */
.testimonial-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}
.testimonial-track {
  display: flex;
  transition: transform 0.5s ease;
}
.testimonial-slide {
  min-width: 100%;
  padding: 2rem;
  text-align: center;
}
.testimonial-quote {
  font-size: 1.5rem;
  font-weight: 500;
  font-style: italic;
  color: var(--text-main);
  margin-bottom: 2rem;
}
.testimonial-author {
  font-weight: 600;
  color: var(--primary);
}
.testimonial-role {
  font-size: 0.875rem;
  color: var(--text-muted);
}
.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}
.carousel-btn {
  width: 44px; height: 44px;
  border-radius: 50%;
  border: 1px solid var(--border-color);
  background: white;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: var(--transition);
}
.carousel-btn:hover {
  background: var(--bg-light);
  color: var(--primary);
}

/* Pricing */
.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}
.toggle-switch {
  position: relative;
  display: inline-block;
  width: 60px;
  height: 34px;
}
.toggle-switch input { opacity: 0; width: 0; height: 0; }
.toggle-slider {
  position: absolute;
  cursor: pointer;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--border-color);
  transition: .4s;
  border-radius: 34px;
}
.toggle-slider:before {
  position: absolute;
  content: "";
  height: 26px; width: 26px;
  left: 4px; bottom: 4px;
  background-color: white;
  transition: .4s;
  border-radius: 50%;
}
input:checked + .toggle-slider { background-color: var(--primary); }
input:checked + .toggle-slider:before { transform: translateX(26px); }

.pricing-card {
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 2.5rem;
  background: white;
  display: flex;
  flex-direction: column;
}
.pricing-card.popular {
  border: 2px solid var(--primary);
  box-shadow: var(--shadow-lg);
  transform: scale(1.05);
  position: relative;
}
.popular-badge {
  position: absolute;
  top: -12px; left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  padding: 0.25rem 1rem;
  border-radius: 12px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}
.pricing-header { margin-bottom: 2rem; border-bottom: 1px solid var(--border-color); padding-bottom: 1.5rem; }
.pricing-price { font-size: 3rem; font-weight: 800; color: var(--text-main); font-family: var(--font-heading); }
.pricing-price span { font-size: 1rem; color: var(--text-muted); font-weight: 400; }
.pricing-features { margin-bottom: 2rem; flex-grow: 1; }
.pricing-features li {
  margin-bottom: 1rem;
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}
.pricing-features li svg { color: var(--primary); flex-shrink: 0; margin-top: 3px; }

/* FAQ Accordion */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--border-color);
}
.faq-question {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 1.5rem 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-main);
  cursor: pointer;
  display: flex; justify-content: space-between; align-items: center;
  font-family: var(--font-body);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}
.faq-answer-content {
  padding-bottom: 1.5rem;
  color: var(--text-muted);
}
.faq-item.active .faq-answer { max-height: 200px; }
.faq-item.active .faq-icon { transform: rotate(180deg); }
.faq-icon { transition: transform 0.3s ease; }

/* Contact Form */
.form-group { margin-bottom: 1.5rem; }
.form-group label { display: block; margin-bottom: 0.5rem; font-weight: 500; color: var(--text-main); }
.form-control {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-family: var(--font-body);
  font-size: 1rem;
  transition: var(--transition);
}
.form-control:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 81, 195, 0.1);
}
.form-message {
  display: none;
  padding: 1rem;
  border-radius: 8px;
  margin-bottom: 1.5rem;
  font-weight: 500;
}
.form-message.success {
  display: block;
  background-color: #DEF7EC;
  color: #03543F;
  border: 1px solid #31C48D;
}
.error-text {
  color: var(--accent);
  font-size: 0.875rem;
  margin-top: 0.25rem;
  display: none;
}
.form-group.has-error .error-text { display: block; }
.form-group.has-error .form-control { border-color: var(--accent); }

/* Footer */
.footer {
  background-color: var(--bg-dark);
  color: #CBD5E1;
  padding: 5rem 0 2rem 0;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 4rem;
  margin-bottom: 4rem;
}
.footer-col h4 {
  color: white;
  margin-bottom: 1.5rem;
  font-size: 1.125rem;
}
.footer-links li { margin-bottom: 0.75rem; }
.footer-links a:hover { color: white; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  text-align: center;
  font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 1024px) {
  h1 { font-size: 3rem; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .pricing-card.popular { transform: scale(1); }
}
@media (max-width: 768px) {
  h1 { font-size: 2.5rem; }
  h2 { font-size: 2rem; }
  .nav-links, .nav-actions { display: none; }
  .mobile-menu-btn { display: block; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; gap: 2rem; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
  .hero { padding: 5rem 0 4rem 0; }
  .hero-actions { flex-direction: column; }
  .btn { width: 100%; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .stat-item h3 { font-size: 2.5rem; }
}

.integration-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
}
.integration-item {
  text-align: center;
  padding: 2rem;
  background: white;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
}

