  color: var(--primary);
}
.testimonial-role {
  font-size: 0.875rem;
  color: var(--text-muted);
}
.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}
.carousel-btn {
  width: 44px; height: 44px;
  border-radius: 50%;
  border: 1px solid var(--border-color);
  background: white;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: var(--transition);
}
.carousel-btn:hover {
  background: var(--bg-light);
  color: var(--primary);
}

/* Pricing */
.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}
.toggle-switch {
  position: relative;
  display: inline-block;
  width: 60px;
  height: 34px;
}
.toggle-switch input { opacity: 0; width: 0; height: 0; }
.toggle-slider {
  position: absolute;
  cursor: pointer;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--border-color);
  transition: .4s;
  border-radius: 34px;
}
.toggle-slider:before {
  position: absolute;
  content: "";
  height: 26px; width: 26px;
  left: 4px; bottom: 4px;
  background-color: white;
  transition: .4s;
  border-radius: 50%;
}
input:checked + .toggle-slider { background-color: var(--primary); }
input:checked + .toggle-slider:before { transform: translateX(26px); }

.pricing-card {
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 2.5rem;
  background: white;
  display: flex;
  flex-direction: column;
}
.pricing-card.popular {
  border: 2px solid var(--primary);
  box-shadow: var(--shadow-lg);
  transform: scale(1.05);
  position: relative;
}
.popular-badge {
  position: absolute;
  top: -12px; left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  padding: 0.25rem 1rem;
  border-radius: 12px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
}
.pricing-header { margin-bottom: 2rem; border-bottom: 1px solid var(--border-color); padding-bottom: 1.5rem; }
.pricing-price { font-size: 3rem; font-weight: 800; color: var(--text-main); font-family: var(--font-heading); }
.pricing-price span { font-size: 1rem; color: var(--text-muted); font-weight: 400; }
.pricing-features { margin-bottom: 2rem; flex-grow: 1; }
.pricing-features li {
  margin-bottom: 1rem;
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}
.pricing-features li svg { color: var(--primary); flex-shrink: 0; margin-top: 3px; }

/* FAQ Accordion */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--border-color);
}
.faq-question {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 1.5rem 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-main);
  cursor: pointer;
  display: flex; justify-content: space-between; align-items: center;
  font-family: var(--font-body);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}
.faq-answer-content {
  padding-bottom: 1.5rem;
  color: var(--text-muted);
}
.faq-item.active .faq-answer { max-height: 200px; }
.faq-item.active .faq-icon { transform: rotate(180deg); }
.faq-icon { transition: transform 0.3s ease; }

/* Contact Form */
.form-group { margin-bottom: 1.5rem; }
.form-group label { display: block; margin-bottom: 0.5rem; font-weight: 500; color: var(--text-main); }
.form-control {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-family: var(--font-body);
  font-size: 1rem;
  transition: var(--transition);
}
.form-control:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 81, 195, 0.1);
}
.form-message {
  display: none;
  padding: 1rem;
  border-radius: 8px;
  margin-bottom: 1.5rem;
  font-weight: 500;
}
.form-message.success {
  display: block;
  background-color: #DEF7EC;
  color: #03543F;
  border: 1px solid #31C48D;
}
.error-text {
  color: var(--accent);
  font-size: 0.875rem;
  margin-top: 0.25rem;
  display: none;
}
.form-group.has-error .error-text { display: block; }
.form-group.has-error .form-control { border-color: var(--accent); }

/* Footer */
.footer {
  background-color: var(--bg-dark);
  color: #CBD5E1;
  padding: 5rem 0 2rem 0;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 4rem;
  margin-bottom: 4rem;
}
.footer-col h4 {
  color: white;
  margin-bottom: 1.5rem;
  font-size: 1.125rem;
}
.footer-links li { margin-bottom: 0.75rem; }
.footer-links a:hover { color: white; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  text-align: center;
  font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 1024px) {
  h1 { font-size: 3rem; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .pricing-card.popular { transform: scale(1); }
}
@media (max-width: 768px) {
  h1 { font-size: 2.5rem; }
  h2 { font-size: 2rem; }
  .nav-links, .nav-actions { display: none; }
  .mobile-menu-btn { display: block; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; gap: 2rem; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
  .hero { padding: 5rem 0 4rem 0; }
  .hero-actions { flex-direction: column; }
  .btn { width: 100%; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .stat-item h3 { font-size: 2.5rem; }
}

.integration-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
}
.integration-item {
  text-align: center;
  padding: 2rem;
  background: white;
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
}

